module count_m (\n    input [63:0] n,\n    input [63:0] t,\n    output reg [63:0] answer\n);\n\n    function automatic [63:0] binom_coeff;\n        input [5:0] n_val;\n        input [5:0] k_val;\n        integer n, k, i;\n        reg [63:0] result;\n        begin\n            n = n_val;\n            k = k_val;\n            if (k > n) begin\n                result = 64'd0;\n            end else if (k == 0 || k == n) begin\n                result = 64'd1;\n            end else begin\n                if (k > n - k) begin\n                    k = n - k;\n                end\n                result = 64'd1;\n                for (i = 1; i <= k; i = i + 1) begin\n                    result = result * (n - i + 1) / i;\n                end\n            end\n            binom_coeff = result;\n        end\n    endfunction\n\n    wire [63:0] X = n + 64'd1;\n    wire is_power = (t != 64'd0) && ((t & (t - 64'd1)) == 64'd0);\n\n    reg [5:0] k;\n    integer idx;\n    reg found;\n    always @(*) begin\n        k = 6'd0;\n        found = 1'b0;\n        if (is_power) begin\n            for (idx = 63; idx >= 0; idx = idx - 1) begin\n                if (!found && t[idx]) begin\n                    k = idx + 1;\n                    found = 1'b1;\n                end\n            end\n        end\n    end\n\n    integer bit_index;\n    reg [5:0] ones_so_far;\n    always @(*) begin\n        answer = 64'd0;\n        ones_so_far = 6'd0;\n        if (is_power) begin\n            for (bit_index = 63; bit_index >= 0; bit_index = bit_index - 1) begin\n                if (X[bit_index]) begin\n                    if (k >= ones_so_far) begin\n                        integer need;\n                        need = k - ones_so_far;\n                        if (need >= 0 && need <= bit_index) begin\n                            answer = answer + binom_coeff(bit_index[5:0], need[5:0]);\n                        end\n                    end\n                    ones_so_far = ones_so_far + 1;\n                end\n            end\n            if (ones_so_far == k) begin\n                answer = answer + 64'd1;\n            end\n            if (k == 6'd1) begin\n                answer = answer - 64'd1;\n            end\n        end\n    end\n\nendmodule